// STAGE 1: Input Parser1 (merged v3) | Mode: Run Once for All Items
// Extracts the rug category, an optional focus keyword and an optional brief request (marketing, supplier, leadership or all) from the Chat Trigger field `chatInput`.
// No external calls.
//
// PARSING RULES
// 1. Focus clause: "focus: <value>" or "focus = <value>" (case-insensitive). The value runs to the end of
//    the line or a semicolon. A comma ends the value ONLY when a category phrase follows it
//    ("focus: washable, outdoor rug"); otherwise commas stay in the focus ("focus: soft, plush").
// 2. The category is detected ONLY in the text outside the focus value. Category words inside the focus
//    value are never used for routing and are never silently dropped (see parse_note).
// 3. A category phrase inside the focus value with no category outside it (e.g. "FOCUS:Washable Hallway
//    Runner") is rejected as ambiguous. Use a comma: "hallway runner, focus: washable".
// 4. If several categories match, precedence is Outdoor Rug > Hallway Runner > Shag Rug > Area Rug.
//    `all_matches` lists every match in that order.
const SEP = '[\\s-]+';
const CATEGORIES = [
  { key: 'outdoor_rug',    display: 'Outdoor Rug',    re: new RegExp(`\\b(?:(?:outdoors?|indoor[\\s/-]+outdoor)(?:${SEP}[a-z]+){0,2}?${SEP}rugs?|patio${SEP}rugs?)\\b`, 'i') },
  { key: 'hallway_runner', display: 'Hallway Runner', re: new RegExp(`\\b(?:hall(?:way)?${SEP}runners?|runner${SEP}rugs?|rug${SEP}runners?)\\b`, 'i') },
  { key: 'shag_rug',       display: 'Shag Rug',       re: new RegExp(`\\bshag(?:gy)?(?:${SEP}[a-z]+)?${SEP}rugs?\\b`, 'i') },
  { key: 'area_rug',       display: 'Area Rug',       re: new RegExp(`\\barea${SEP}rugs?\\b`, 'i') },
];
const FOCUS_RE = /\bfocus\s*[:=]\s*([^\n;]*)/i;
const MAX_FOCUS_LENGTH = 60;

const findMatches = (text) => CATEGORIES.filter((c) => c.re.test(text));

return $input.all().map((item) => {
  const original = String(item.json.chatInput ?? '').trim();

  let focusKeyword = null;
  let focusValue = '';
  let categoryText = original;

  const m = original.match(FOCUS_RE);
  if (m) {
    focusValue = m[1];
    const valueStart = m.index + m[0].length - m[1].length;
    // A comma followed by a category phrase ends the focus value.
    for (let i = focusValue.indexOf(','); i !== -1; i = focusValue.indexOf(',', i + 1)) {
      if (findMatches(focusValue.slice(i + 1)).length > 0) { focusValue = focusValue.slice(0, i); break; }
    }
    categoryText = `${original.slice(0, m.index)} ${original.slice(valueStart + focusValue.length)}`;
    focusKeyword = focusValue.replace(/\s+/g, ' ').replace(/[.!?\s]+$/, '').trim().toLowerCase().slice(0, MAX_FOCUS_LENGTH) || null;
  }

  const matches = findMatches(categoryText);
  const selected = matches[0] ?? null;
  const inFocus = findMatches(focusValue).map((c) => c.display);

  let parseNote = null;
  let errorReason = null;
  if (!selected) {
    errorReason = 'no_category';
    if (inFocus.length > 0) {
      errorReason = 'category_in_focus_ambiguous';
      parseNote = `I found "${inFocus[0]}" inside the focus value, so I can't tell whether it is the category or part of the focus. Separate them with a comma, e.g. "${inFocus[0].toLowerCase()}, focus: washable".`;
    }
  } else if (inFocus.length > 0) {
    parseNote = `Category words inside the focus value were kept as focus text and not used for routing: ${inFocus.join(', ')}.`;
  }

  // Brief request: needs the word "brief"; the audience word picks which one (marketing > supplier > leadership); "brief" alone means all three
  const lower = original.toLowerCase();
  let brief = null;
  if (/\bbriefs?\b/.test(lower)) {
    if (/\b(marketing|creative|campaign)\b/.test(lower)) brief = 'marketing';
    else if (/\b(supplier|sourcing|product development)\b/.test(lower)) brief = 'supplier';
    else if (/\b(leadership|executive|decision[\s-]makers?)\b/.test(lower)) brief = 'leadership';
    else brief = 'all';
  }

  return {
    json: {
      // Core fields
      original_message: original,
      category: selected ? selected.display : null,
      focus_keyword: focusKeyword,
      is_valid: selected !== null,
      all_matches: matches.map((c) => c.display),
      parse_note: parseNote,
      // Convenience fields (compatible with the earlier v2 parser)
      selectedCategory: selected ? selected.display : null,
      categoryKey: selected ? selected.key : null,
      focus: focusKeyword ?? '',
      hasCategory: selected !== null,
      hasValidInput: selected !== null,
      errorReason,
      brief,
    },
  };
});

// STAGE 1: Error Response1 (merged v4) | Mode: Run Once for All Items
const NO_CATEGORY =
  'I could not detect a rug category. Please include one of:\n- Area Rug\n- Outdoor Rug\n- Hallway Runner\n- Shag Rug\n\n**Example input:**\noutdoor rug, focus: washable';
const NO_PRODUCTS =
  'No products were returned for this category. The pre-scraped dataset may not have refreshed yet, or the program API may be temporarily unavailable. Try again in a few minutes, or contact the program team if this persists.';
const UNKNOWN = 'An unknown error occurred. Please try again or contact the program team.';
const AI_UNAVAILABLE = 'The AI service could not be reached or returned an error (for example, the API account may be out of credits). Please try again later or contact the program team.';
const NO_VALID_PRODUCTS = 'None of the products returned matched the selected category, so there is nothing to analyse. Try another category or contact the program team.';
const NO_SEGMENTS = 'I could not identify any clear trend segments from the available data (too little or too mixed). Try a different category or focus.';
const AI_OUTPUT_INVALID = 'The AI returned an answer I could not read safely. Please try again.';

const inferReason = (json) => {
  if (json.errorReason) return json.errorReason;
  const apiProblem = json.error !== undefined || !(Number(json.total_products) > 0);
  return apiProblem ? 'no_products' : 'unknown';
};

return $input.all().map((item, index) => {
  const reason = inferReason(item.json);

  let message;
  if (reason === 'no_category') {
    message = NO_CATEGORY;
  } else if (reason === 'category_in_focus_ambiguous') {
    message = `${NO_CATEGORY}\n\n${item.json.parse_note || ''}`.trim();
  } else if (reason === 'no_products') {
    message = NO_PRODUCTS;
  } else if (reason === 'ai_unavailable') {
    message = AI_UNAVAILABLE;
  } else if (reason === 'no_valid_products') {
    message = NO_VALID_PRODUCTS;
  } else if (reason === 'no_segments') {
    message = NO_SEGMENTS;
  } else if (reason === 'ai_output_invalid') {
    message = AI_OUTPUT_INVALID;
  } else {
    message = UNKNOWN;
  }

  return { pairedItem: { item: index }, json: { output: message, error: true, message, reason } };
});

// Reshape FastAPI response to legacy { amazonProducts } shape
// expected by Merge All Data1 and the downstream AI stages (Stages 3–7).
const r = $input.first().json;
const products = r.products || [];

return [{
  json: {
    amazonProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString()
    })),
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString()
  }
}];

// Merge Social Data1 | Mode: Run Once for All Items
// Merges Instagram, Pinterest and Blogs into the structure Stages 3-7 read:
//   socialData.{instagram,pinterest,blogs} (arrays), socialImages, totalSocialItems,
//   totalSocialImages, externApiStatus.
// Safeguards added to the course version: each source is read BY NODE NAME; base64 images are removed
// from the raw items (they live only in socialImages, max 3 per source, MIME and size checked);
// usernames/authors are dropped; links/emails/@mentions/phone numbers are scrubbed from text; long text is
// truncated; failed vs empty vs not-run is reported.
// Third-party text is DATA only. Field names follow the API: { items: [...] }, image_base64, image_mime_type.
const MAX_IMAGES_PER_SOURCE = 3;
const MAX_BASE64_CHARS = 400000;           // ~300 KB image; larger images are skipped
const MAX_ITEMS = 50;
const MAX_STRING = 2000;
const MAX_ARRAY = 50;
const DROP_KEYS = new Set(['image_base64', 'imageBase64', 'image_b64', 'base64', 'username', 'user', 'user_name',
  'handle', 'author', 'owner', 'profile', 'profile_url', 'email', 'phone']);
const LIST_KEYS = ['items', 'posts', 'pins', 'articles', 'blogs', 'results', 'data'];
const MIME_OK = /^image\/(png|jpe?g|webp|gif)$/i;

// Update 2: scrub personal data from free text before it flows to later (AI) stages (best effort):
// links, emails, @mentions and phone numbers. Structured fields such as `url` are left untouched.
const TEXT_KEYS = new Set(['caption', 'text', 'description', 'title', 'headline', 'name', 'content', 'body', 'summary']);
const scrubStats = { links: 0, emails: 0, mentions: 0, phones: 0 };
const scrub = (s, count = true) => {
  const tick = (k) => { if (count) scrubStats[k] += 1; };
  return s
    .replace(/\b(?:https?:\/\/|www\.)\S*[^\s.,;:!?)\]"']/gi, () => { tick('links'); return '[link]'; })   // keeps trailing punctuation
    .replace(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g, () => { tick('emails'); return '[email]'; })
    .replace(/(^|[^\w])@\w{2,}(?:\.\w+)*/g, (m, pre) => { tick('mentions'); return `${pre}[user]`; })
    .replace(/(?<![\w$])\+?\d[\d\s().-]{7,}\d(?![\w%])/g, (m) => {
      const digits = m.replace(/\D/g, '').length;
      if (digits < 9 || digits > 15 || /^\d{4}-\d{2}-\d{2}/.test(m)) return m;   // not a phone number (dates, sizes)
      tick('phones');
      return '[phone]';
    });
};

const readSource = (name) => {
  try { return { ran: true, raw: $(name).all().map((i) => i.json) }; } catch (e) { return { ran: false, raw: [] }; }
};
const listOf = (raw) => {
  if (raw.length === 1 && raw[0] && typeof raw[0] === 'object') {
    for (const k of LIST_KEYS) if (Array.isArray(raw[0][k])) return raw[0][k];
  }
  return raw;
};
const statusOf = (src, list) => {
  if (!src.ran) return 'not_run';
  if (src.raw.length === 1 && src.raw[0] && src.raw[0].error !== undefined) return 'failed';
  return list.length === 0 ? 'empty' : 'ok';
};
// Keep primitives and arrays of primitives; drop denied keys and nested objects; truncate text.
const sanitize = (item) => {
  const out = {};
  for (const [k, v] of Object.entries(item)) {
    if (DROP_KEYS.has(k)) continue;
    if (typeof v === 'string') out[k] = (TEXT_KEYS.has(k) ? scrub(v) : v).slice(0, MAX_STRING);
    else if (typeof v === 'number' || typeof v === 'boolean' || v === null) out[k] = v;
    else if (Array.isArray(v) && v.every((x) => ['string', 'number', 'boolean'].includes(typeof x))) {
      out[k] = v.slice(0, MAX_ARRAY).map((x) => (typeof x === 'string' ? x.slice(0, 200) : x));
    }
  }
  return out;
};
const imagesFrom = (list, source, stats) => {
  const out = [];
  for (const item of list) {
    if (out.length >= MAX_IMAGES_PER_SOURCE) break;
    let data = item.image_base64;
    if (!data) continue;
    let mime = String(item.image_mime_type || 'image/jpeg');
    if (typeof data !== 'string') { stats.skipped_invalid += 1; continue; }
    const uri = data.startsWith('data:') ? data.match(/^data:([^;,]+);base64,([\s\S]+)$/) : null;
    if (uri) { mime = uri[1]; data = uri[2]; }
    if (!MIME_OK.test(mime)) { stats.skipped_invalid += 1; continue; }
    if (data.length > MAX_BASE64_CHARS) { stats.skipped_oversize += 1; continue; }
    if (!/^[A-Za-z0-9+/=\s]+$/.test(data)) { stats.skipped_invalid += 1; continue; }
    out.push({ source, id: item.id, caption: scrub(String(item.caption || ''), false).slice(0, 500), image_base64: data.replace(/\s+/g, ''), mime_type: mime.toLowerCase() });
  }
  return out;
};

const stats = { skipped_oversize: 0, skipped_invalid: 0 };
const read = (name, withImages) => {
  const src = readSource(name);
  const list = listOf(src.raw).filter((p) => p && typeof p === 'object').slice(0, MAX_ITEMS);
  const status = statusOf(src, list);
  const failedOrMissing = status === 'failed' || status === 'not_run';
  return {
    status,
    items: failedOrMissing ? [] : list.map(sanitize),
    images: withImages && !failedOrMissing ? imagesFrom(list, name === 'Fetch Instagram' ? 'instagram' : 'pinterest', stats) : [],
    snapshot: (!failedOrMissing && typeof src.raw[0]?.scraped_at === 'string') ? src.raw[0].scraped_at.slice(0, 40) : null,
  };
};

const instagram = read('Fetch Instagram', true);
const pinterest = read('Fetch Pinterest', true);
const blogs = read('Fetch Blogs', false);
const marketSrc = readSource('Fetch Market Data');     // not merged here (Stage 5 reads it); status only
const marketStatus = statusOf(marketSrc, listOf(marketSrc.raw));

const socialImages = [...instagram.images, ...pinterest.images];
const label = (s) => (s.items.length > 0 ? 'success' : 'empty_or_failed');   // course-compatible labels

return [{
  json: {
    socialData: { instagram: instagram.items, pinterest: pinterest.items, blogs: blogs.items },
    socialImages,
    totalSocialItems: instagram.items.length + pinterest.items.length + blogs.items.length,
    totalSocialImages: socialImages.length,
    externApiStatus: { instagram: label(instagram), pinterest: label(pinterest), blogs: label(blogs) },
    // Extra detail: why a source has no data (ok | empty | failed | not_run)
    sourceDetail: { instagram: instagram.status, pinterest: pinterest.status, blogs: blogs.status, market: marketStatus },
    snapshotDates: { instagram: instagram.snapshot, pinterest: pinterest.snapshot, blogs: blogs.snapshot },
    imageStats: stats,
    scrubStats,
  },
}];

// Merge Image Analysis | Mode: Run Once for All Items
// Caption/hashtag trend analysis of the Instagram + Pinterest items (text only; the images themselves
// are analysed in a later stage). Output feeds Stage 3 (Micro-Segment Identifier).
// Note: tags that only repeat the search (e.g. #arearug, #modernrunner for runners) and generic community tags
// (#ruglovers, #interiordesign...) are removed from the rankings and reported separately.
const MAX_HASHTAGS = 20;
const CAPTION_BUDGET = 2000;      // characters, shared equally by the sources that have captions

// Step A: tags that only repeat the search itself (every post was selected for being an "area rug")
// carry no trend information. They are removed from the ranking and reported separately.
const QUERY_TAGS = {
  area_rug: ['#arearug', '#arearugs'],
  outdoor_rug: ['#outdoorrug', '#outdoorrugs'],
  hallway_runner: ['#hallwayrunner', '#hallwayrunners', '#runnerrug', '#runnerrugs'],
  shag_rug: ['#shagrug', '#shagrugs'],
};
const GENERIC_RUG_TAGS = ['#rug', '#rugs'];
// A tag containing one of these words repeats the search only if nothing meaningful is left once the category word
// and filler words are removed: #hallwaydesign, #runnerdecor are search tags; #bohorunner (boho), #woolrunner (wool),
// #kitchenrunner (kitchen) are kept because they say something about style, material or use.
const CORE_WORDS = { area_rug: ['arearug'], outdoor_rug: ['outdoor'], hallway_runner: ['runner', 'hallway'], shag_rug: ['shag'] };
// Generic community tags: popular on every home-decor post, so they carry no trend information
const GENERIC_TAGS = new Set(['#ruglovers', '#ruglove', '#rugstyle', '#rugsofinstagram', '#interiordesign', '#interior', '#interiors', '#homedecor', '#home',
  '#decor', '#livingroom', '#homeinspo', '#homemakeover', '#design', '#style', '#instahome', '#interiorstyling', '#interiorinspiration', '#interiorinspo',
  '#homeinteriors', '#homestyle', '#homedetails', '#interiordecor', '#welcomehome', '#designer', '#homesweethome', '#instadecor']);
const FILLER = ['inspiration', 'inspo', 'styling', 'interiors', 'interior', 'design', 'decor', 'ideas', 'goals', 'style', 'home', 'rugs', 'rug', 'love'];
let categoryKey = null;
try { categoryKey = $('Get Category Key').first().json.categoryKey; } catch (e) { /* optional */ }
const excludedTags = new Set([...(QUERY_TAGS[categoryKey] || []), ...GENERIC_RUG_TAGS]);
const onlyRepeatsSearch = (tag) => {
  const words = CORE_WORDS[categoryKey] || [];
  let rest = tag.slice(1);
  if (!words.some((w) => rest.includes(w))) return false;
  for (const w of [...words, ...FILLER]) rest = rest.split(w).join('');
  return rest.length < 3;
};
const isQueryTag = (tag) => excludedTags.has(tag) || onlyRepeatsSearch(tag);
const isGenericTag = (tag) => GENERIC_TAGS.has(tag);

const social = $('Merge Social Data1').first().json;
const data = social.socialData || {};
const instagram = data.instagram || [];
const pinterest = data.pinterest || [];

// "#NeutralRug", "neutralrug" and "#neutralrug!" all become "#neutralrug"
const normTag = (t) => {
  const s = String(t).trim().toLowerCase().replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, '');
  return s ? `#${s}` : null;
};
const tagsOf = (post) => {
  let raw = post.hashtags;
  if (typeof raw === 'string') raw = raw.split(/[\s,]+/);
  if (!Array.isArray(raw) || raw.length === 0) raw = String(post.caption || '').match(/#[\p{L}\p{N}_]+/gu) || [];
  return [...new Set(raw.map(normTag).filter(Boolean))];      // each tag counted once per post
};
const toInsight = (source) => (post) => ({
  source,
  caption: String(post.caption || '').slice(0, 500),
  hashtags: tagsOf(post),
  engagement: Math.max(0, Number(post.engagement) || 0),
});
const insights = [...instagram.map(toInsight('instagram')), ...pinterest.map(toInsight('pinterest'))];

const counts = new Map();
for (const i of insights) for (const t of i.hashtags) counts.set(t, (counts.get(t) || 0) + 1);
const byCount = (a, b) => b[1] - a[1] || a[0].localeCompare(b[0]);
const toList = (entries) => entries.map(([tag, count]) => ({ tag, count }));
const ranked = [...counts.entries()].filter(([tag]) => !isQueryTag(tag) && !isGenericTag(tag)).sort(byCount);
const topHashtags = toList(ranked.slice(0, MAX_HASHTAGS));
const excludedQueryTags = toList([...counts.entries()].filter(([tag]) => isQueryTag(tag)).sort(byCount));
const genericTagsRemoved = toList([...counts.entries()].filter(([tag]) => !isQueryTag(tag) && isGenericTag(tag)).sort(byCount));

// Step B: engagement-weighted ranking. Engagement is not comparable across sources, so each post's weight is
// its share of ITS OWN source's total engagement. A tag's score is the sum of the weights of the posts that use
// it, averaged over the sources that have engagement data -> "share of engagement" in percent.
const sourceTotals = { instagram: 0, pinterest: 0 };
for (const i of insights) sourceTotals[i.source] += i.engagement;
const activeSources = Object.values(sourceTotals).filter((t) => t > 0).length;
const shareSum = new Map();
for (const i of insights) {
  if (!sourceTotals[i.source]) continue;
  const w = i.engagement / sourceTotals[i.source];
  for (const t of i.hashtags) shareSum.set(t, (shareSum.get(t) || 0) + w);
}
const sharePct = (tag) => Math.round(((shareSum.get(tag) || 0) / (activeSources || 1)) * 1000) / 10;
const topByEngagement = ranked
  .map(([tag, count]) => ({ tag, count, engagement_share_pct: sharePct(tag) }))
  .sort((a, b) => b.engagement_share_pct - a.engagement_share_pct || b.count - a.count || a.tag.localeCompare(b.tag))
  .slice(0, MAX_HASHTAGS);

// Step D: attribute mentions. The captions say far more than the hashtags (materials, construction, patterns,
// styles, features, where the rug is used). For every attribute value: in how many posts it is mentioned (counted
// once per post, from the caption text and the words of the hashtags) and its engagement share, computed like Step B.
// Words hidden inside compound hashtags (e.g. #woolrunner) are not detected; the caption usually repeats them.
const ATTR_WORDS = {
  material: { wool: /\bwool(?:len)?\b|\bmerino\b/, cotton: /\bcotton\b/, jute: /\bjute\b/, hemp: /\bhemp\b/, silk: /\bsilk\b/, polyester: /\bpolyester\b/, polypropylene: /\bpolypropylene\b/,
    nylon: /\bnylon\b/, viscose: /\bviscose\b|\brayon\b/, acrylic: /\bacrylic\b/, microfiber: /\bmicrofib(?:er|re)\b/, chenille: /\bchenille\b/, blend: /\bblend(?:ed)?\b/,
    synthetic: /\bsynthetic\b/, natural_fibers: /\bnatural (?:fib(?:er|re)s?|materials?)\b/ },
  construction: { hand_tufted: /\bhand[- ]?tufted\b/, tufted: /(?<!hand[- ]?)\btufted\b/, hand_knotted: /\bhand[- ]?knotted\b/, handwoven: /\bhand[- ]?woven\b/,
    flatweave: /\bflat[- ]?weave\b|\bkilim\b|\bdhurrie\b/, braided: /\bbraided\b/, block_printed: /\bblock[- ]?print(?:ed|ing)?\b/, machine_made: /\bmachine[- ](?:made|woven)\b/,
    loop_and_cut: /\bloop (?:and|&) cut\b|\bcut (?:and|&) loop\b/, handmade: /\bhand[- ]?made\b|\bhandcrafted\b/ },
  pile: { low: /\blow[- ]?(?:pile|profile)\b/, medium: /\bmedium[- ]?pile\b/, high: /\bhigh[- ]?pile\b/, shag: /\bshag(?:gy)?\b/ },
  pattern: { striped: /\bstrip(?:e|ed|es)\b/, wavy: /\bwav(?:y|es?)\b/, geometric: /\bgeometric\b|\bdiamond\b|\blattice\b/, checkered: /\bcheck(?:ered|ers?)\b|\bchecks\b|\bplaid\b/,
    abstract: /\babstract\b/, floral: /\bfloral\b|\bflowers?\b|\bbotanical\b/, medallion: /\bmedallion\b/, persian_oriental: /\bpersian\b|\borient(?:al)?\b/,
    tribal: /\btribal\b|\baztec\b|\bsouthwestern\b/, moroccan: /\bmoroccan\b/, trellis: /\btrellis\b/, chevron: /\bchevron\b|\bherringbone\b/, distressed: /\bdistressed\b|\bfaded\b/,
    textured: /\btextur(?:ed|e)\b|\bhigh[- ]?low\b|\bcarved\b/, border: /\bborders?\b/, solid: /\bsolid\b/ },
  style: { modern: /\bmodern\b/, contemporary: /\bcontemporary\b/, minimalist: /\bminimali(?:st|stic)\b/, vintage: /\bvintage\b|\bretro\b/, traditional: /\btraditional\b|\bclassic\b/,
    bohemian: /\bboho\b|\bbohemian\b/, farmhouse: /\bfarmhouse\b/, coastal: /\bcoastal\b|\bnautical\b/, scandinavian: /\bscandinavian\b|\bscandi\b/, industrial: /\bindustrial\b/,
    mid_century: /\bmid[- ]?century\b/, maximalist: /\bmaximalist\b/, rustic: /\brustic\b/, luxury: /\bluxur(?:y|ious)\b|\bluxe\b/, organic: /\borganic\b/ },
  colors: { neutral: /\bneutrals?\b/, cream: /\bcream(?:y)?\b/, white: /\bwhite\b/, gray: /\bgr[ae]y\b|\bsilver\b/, charcoal: /\bcharcoal\b/, beige: /\bbeige\b|\boatmeal\b/, taupe: /\btaupe\b/,
    brown: /\bbrown\b|\bchocolate\b/, blue: /\bblue\b|\bdenim\b/, navy: /\bnavy\b/, teal: /\bteal\b|\bturquoise\b/, green: /\bgreen\b|\bsage\b|\bemerald\b/, olive: /\bolive\b/,
    red: /\bred\b/, burgundy: /\bburgundy\b|\bwine\b/, coral: /\bcoral\b/, orange: /\borange\b|\brust\b/, pink: /\bpink\b|\bblush\b|\brose\b/, purple: /\bpurple\b|\blavender\b/,
    multi: /\bmulti[- ]?colou?r(?:ed)?\b|\bcolou?rful\b/, black: /\bblack\b/, gold: /\bgold\b/, ivory: /\bivory\b/, tan: /\btan\b|\bcamel\b/, yellow: /\byellow\b/,
    mustard: /\bmustard\b|\bochre\b/, terracotta: /\bterra ?cotta\b/ },
  features: { washable: /\bwashable\b|\bmachine[- ]wash/, non_slip: /\bnon[- ]?slip\b|\banti[- ]?(?:slip|skid)\b|\bskid\b/, stain_resistant: /\bstain[- ]?(?:resistant|proof)\b/,
    water_resistant: /\bwater[- ]?(?:resistant|proof|repellent)\b|\bwaterproof\b/, pet_friendly: /\bpet[- ]?friendly\b/, easy_clean: /\beasy[- ](?:clean|care)\b/,
    eco_friendly: /\beco[- ]?friendly\b|\bsustainable\b|\bbiodegradable\b/, soft_plush: /\bplush\b|\bfluffy\b/, lightweight: /\blightweight\b/, durable: /\bdurable\b|\bwear[- ]resistant\b/ },
  usage: { kitchen: /\bkitchens?\b/, entryway: /\bentry(?:way)?\b|\bfoyer\b/, stairs: /\bstairs?\b|\bstaircase\b/, corridor: /\bcorridors?\b/, bedroom: /\bbedrooms?\b/, bathroom: /\bbathrooms?\b/,
    living_room: /\bliving[- ]?room\b/, dining_room: /\bdining[- ]?room\b/, laundry_room: /\blaundry\b/, home_office: /\b(?:home )?office\b/, high_traffic: /\bhigh[- ]traffic\b/, narrow_spaces: /\bnarrow\b/ },
};
const mentionText = (i) => `${i.caption} ${i.hashtags.map((h) => h.slice(1)).join(' ')}`.toLowerCase();
const mentionTexts = insights.map(mentionText);
const attributeMentions = {};
for (const [facet, table] of Object.entries(ATTR_WORDS)) {
  const rows = [];
  for (const [value, re] of Object.entries(table)) {
    let posts = 0;
    let weight = 0;
    insights.forEach((i, idx) => {
      if (!re.test(mentionTexts[idx])) return;
      posts += 1;
      if (sourceTotals[i.source]) weight += i.engagement / sourceTotals[i.source];
    });
    if (posts) rows.push({ value, posts, engagement_share_pct: Math.round((weight / (activeSources || 1)) * 1000) / 10 });
  }
  attributeMentions[facet] = rows.sort((a, b) => b.posts - a.posts || b.engagement_share_pct - a.engagement_share_pct || a.value.localeCompare(b.value)).slice(0, 8);
}

// Step C: balanced caption sample. Equal share of the budget per source; within a source the captions with the
// highest engagement come first (ties keep the API order); whole captions first, cut at a word boundary.
const engagementOf = (p) => Math.max(0, Number(p.engagement) || 0);
const sample = (posts, budget) => {
  let text = '';
  for (const p of [...posts].sort((a, b) => engagementOf(b) - engagementOf(a))) {
    const c = String(p.caption || '').replace(/\s+/g, ' ').trim();
    if (!c) continue;
    if (text.length + c.length + 1 > budget) {
      const room = budget - text.length - 1;
      if (room > 20) text += ` ${c.slice(0, room).replace(/\s+\S*$/, '')}`;
      break;
    }
    text += (text ? ' ' : '') + c;
  }
  return text.trim();
};
const sources = [instagram, pinterest].filter((posts) => posts.some((p) => p.caption));
const share = sources.length ? Math.floor(CAPTION_BUDGET / sources.length) : 0;
const captionInsights = sources.map((posts) => sample(posts, share)).filter(Boolean).join(' ');

const detail = social.sourceDetail || {};
const analyzed = insights.length;

// The posts' OWN dates: the snapshot date says when the data was collected, these say when the content was written
const DATE_KEYS = ['posted_at', 'created_at', 'timestamp', 'published_at', 'date'];
const OLD_POSTS_DAYS = 180;      // if even the newest post is older than this, the signals describe the past
const toTime = (v) => {
  if (typeof v === 'number' && Number.isFinite(v)) return v < 1e12 ? v * 1000 : v;
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : null;
};
const postTime = (p) => { for (const k of DATE_KEYS) { const t = toTime(p[k]); if (t !== null) return t; } return null; };
const dateRange = (posts) => {
  const ts = posts.map(postTime).filter((t) => t !== null).sort((a, b) => a - b);
  if (!ts.length) return { n: 0, oldest: null, newest: null, newest_age_days: null };
  const day = (t) => new Date(t).toISOString().slice(0, 10);
  return { n: ts.length, oldest: day(ts[0]), newest: day(ts[ts.length - 1]), newest_age_days: Math.max(0, Math.floor((Date.now() - ts[ts.length - 1]) / 86400000)) };
};
const postDates = { instagram: dateRange(instagram), pinterest: dateRange(pinterest) };

// Update 1: data-quality warnings travel with the summary so later stages (and readers) can see them.
const MIN_POSTS = 20;       // fewer analysed posts than this = weak evidence
const STALE_DAYS = 30;      // snapshots older than this are "not current"
const ageDays = (iso) => {
  const t = Date.parse(iso);
  return Number.isFinite(t) ? Math.max(0, Math.floor((Date.now() - t) / 86400000)) : null;
};
let amazonSnapshot = null;
try { amazonSnapshot = $('Reshape Amazon Response').first().json.scrapedAt || null; } catch (e) { /* other branch may not have run */ }
const snapshots = {
  instagram: social.snapshotDates?.instagram ?? null,
  pinterest: social.snapshotDates?.pinterest ?? null,
  blogs: social.snapshotDates?.blogs ?? null,
  amazon: amazonSnapshot,
};
const dataFreshness = Object.fromEntries(Object.entries(snapshots).map(([k, v]) => [k, { snapshot: v, age_days: v ? ageDays(v) : null }]));
const DATASET_NOTE = 'Social and blog signals come from a curated, stored snapshot (the Extern API, a stand-in for a third-party trend provider), not a live feed.';
const dataWarnings = [DATASET_NOTE];
if (analyzed < MIN_POSTS) dataWarnings.push(`Only ${analyzed} social posts analysed (fewer than ${MIN_POSTS}): treat counts and rankings as weak evidence.`);
for (const [k, r] of Object.entries(postDates)) {
  if (r.n > 0 && r.newest_age_days > OLD_POSTS_DAYS) dataWarnings.push(`${k} posts are dated ${r.oldest} to ${r.newest} (the newest is ${r.newest_age_days} days old): they show past interest, not current trends.`);
}
for (const [k, f] of Object.entries(dataFreshness)) {
  if (f.age_days !== null && f.age_days > STALE_DAYS) dataWarnings.push(`${k} data snapshot is ${f.age_days} days old (${String(f.snapshot).slice(0, 10)}): not current.`);
}
const anyPostDates = Object.values(postDates).some((r) => r.n > 0);
if (Object.values(dataFreshness).every((f) => f.age_days === null)) dataWarnings.push(`The snapshot collection date was not provided by the API (being confirmed with the program team).${anyPostDates ? '' : ' Post dates are also missing: data freshness is unknown.'}`);

return [{
  json: {
    imageAnalysis: {
      trend_summary: {
        top_hashtags: topHashtags,                 // ranked by number of posts; query-defining tags removed
        top_hashtags_by_engagement: topByEngagement,   // ranked by share of engagement (Step B)
        engagement_basis: "engagement_share_pct = % of each source's total engagement held by posts using the tag, averaged across sources",
        excluded_query_tags: excludedQueryTags,    // tags that only repeat the search, e.g. [{ tag: '#arearug', count: 12 }]
        generic_tags_removed: genericTagsRemoved,  // generic community tags, e.g. #ruglovers, #interiordesign
        attribute_mentions: attributeMentions,     // per attribute group: posts mentioning each value (Step D)
        attribute_mentions_basis: 'Counted once per post from the caption text and hashtag words; engagement_share_pct is computed like the hashtag ranking. Words inside compound hashtags (e.g. #woolrunner) are not detected.',
        total_posts_analyzed: analyzed,
        instagram_count: instagram.length,
        pinterest_count: pinterest.length,
        post_dates: postDates,                     // each source's oldest/newest post date and the newest post's age
        caption_insights: captionInsights,
        data_warnings: dataWarnings,               // sample size and data freshness (Update 1)
      },
      source: 'social_captions_and_hashtags',
    },
    socialInsights: insights,      // caption/hashtag objects ("socialImages" is reserved for real images)
    analysisSuccess: analyzed > 0,
    reason: analyzed > 0 ? 'Using social captions and hashtags for trend analysis' : 'No Instagram or Pinterest posts available for analysis',
    dataFreshness,
    sourcesUnavailable: Object.entries(detail).filter(([, s]) => s === 'failed' || s === 'not_run').map(([k]) => k),
  },
}];

// Get Category Key | Mode: Run Once for All Items
const VALID_KEYS = ['area_rug', 'outdoor_rug', 'hallway_runner', 'shag_rug'];
const parsed = $('Input Parser1').first().json;

if (!VALID_KEYS.includes(parsed.categoryKey)) {
  throw new Error(`Get Category Key: unexpected categoryKey "${parsed.categoryKey}"`);
}

return [{
  json: {
    categoryKey: parsed.categoryKey,
    selectedCategory: parsed.selectedCategory,
    focus: parsed.focus || '',   // only used if an endpoint accepts it
  },
}];

// Remove Invalid Products (course code + guards)
const input = $input.first().json;
let output = input.output;
const amazonProducts = $('Reshape Amazon Response').first().json.amazonProducts || [];
const fail = (reason, error) => [{ json: { filteredProducts: [], totalFiltered: 0, classificationSummary: {}, error, errorReason: reason } }];

// The Judge failed (timeout, quota, empty answer): stop cleanly
if (input.error !== undefined || output === undefined || output === null || (typeof output === 'string' && output.trim() === '')) {
  return fail('ai_unavailable', 'Classifier unavailable');
}

// Parse AI output (handle markdown code blocks if present)
if (typeof output === 'string') {
  output = output.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try {
    output = JSON.parse(output);
  } catch (e) {
    return fail('ai_output_invalid', 'Failed to parse classifier output');
  }
}
if (!output || typeof output !== 'object') return fail('ai_output_invalid', 'Failed to parse classifier output');

const classifications = Array.isArray(output.classifications) ? output.classifications : [];
const norm = (u) => String(u || '').trim().split('?')[0].replace(/\/+$/, '');

// Filter to only matching products
const matchingUrls = new Set(
  classifications
    .filter(c => c && c.match_status === 'match' && c.confidence !== 'low')
    .map(c => norm(c.url))
);

const filteredProducts = amazonProducts
  .filter(p => matchingUrls.has(norm(p.url)))
  .map(p => {
    const classification = classifications.find(c => c && norm(c.url) === norm(p.url));
    return {
      ...p,
      classification_reasoning: String(classification?.reasoning || '').slice(0, 200)
    };
  });

return [{
  json: {
    filteredProducts: filteredProducts,
    totalFiltered: filteredProducts.length,
    classificationSummary: output.summary || {},
    errorReason: filteredProducts.length === 0 ? 'no_valid_products' : null
  }
}];

// Save Standardized Data (course code + guards)
const input = $input.first().json;
let output = input.output;
const fail = (reason, error) => [{ json: { error, errorReason: reason, attributeData: null, products: [], summary: {} } }];

// Nothing to standardize (the Judge failed or removed every product)
const up = $('Remove Invalid Products1').first().json;
if ((up.filteredProducts || []).length === 0) return fail(up.errorReason || 'no_valid_products', 'No products to standardize');

if (input.error !== undefined || output === undefined || output === null || (typeof output === 'string' && output.trim() === '')) {
  return fail('ai_unavailable', 'Attribute extraction unavailable');
}
// Parse attribute extraction output
if (typeof output === 'string') {
  output = output.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try {
    output = JSON.parse(output);
  } catch (e) {
    return fail('ai_output_invalid', 'Failed to parse attributes');
  }
}
if (!output || typeof output !== 'object') return fail('ai_output_invalid', 'Failed to parse attributes');

return [{
  json: {
    attributeData: output,
    products: output.products || [],
    summary: output.summary || {},
    errorReason: null
  }
}];

