parameters.jsCode:
// Save Trend List (guards + evidence check)
// Keeps interface: microSegments, segmentCount (plus errorReason and data_warnings).
// - No invented fallback: failures give an empty list and a reason.
// - Numbers the AI wrote (counts, percentages, prices, product claims) are removed: the AI cannot verify them.
// - Verified evidence is added by code: for each segment, how many social posts mention the segment's own attributes
//   (taken from the caption analysis), a support level, and a confidence that is never above "medium"
//   (the data is a small, old, curated snapshot).
const input = $input.first().json;
let output = input.output;
const out = (segments, errorReason) => [{ json: { microSegments: segments, segmentCount: segments.length, errorReason, data_warnings: warnings } }];

let summary = {};
try { summary = $('Merge Image Analysis').first().json.imageAnalysis.trend_summary || {}; } catch (e) { /* optional */ }
const warnings = Array.isArray(summary.data_warnings) ? summary.data_warnings : [];
const totalPosts = Number(summary.total_posts_analyzed) || 0;
const mentions = summary.attribute_mentions || {};

// Upstream failure (no products, or attributes could not be extracted)
const up = $('Save Standardized Data1').first().json;
if (up.errorReason) return out([], up.errorReason);

if (input.error !== undefined || output === undefined || output === null || (typeof output === 'string' && output.trim() === '')) return out([], 'ai_unavailable');

// Parse micro-segment output
if (typeof output === 'string') {
  output = output.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try {
    output = JSON.parse(output);
  } catch (e) {
    // the model sometimes adds words around the JSON: try the part between the first { and the last }
    const first = output.indexOf('{');
    const last = output.lastIndexOf('}');
    try {
      output = JSON.parse(output.slice(first, last + 1));
    } catch (e2) {
      return out([], 'ai_output_invalid');
    }
  }
}
if (!output || !Array.isArray(output.micro_segments)) return out([], 'ai_output_invalid');

const clean = (s, n) => String(s ?? '').replace(/[\u2010-\u2015]/g, '-').replace(/\s+/g, ' ').trim().slice(0, n);   // the AI often writes non-breaking hyphens
const list = (v, n, m) => (Array.isArray(v) ? v : []).map((x) => clean(x, n)).filter(Boolean).slice(0, m);
const keyword = (k) => String(k).toLowerCase().replace(/[^a-z0-9 -]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 30);   // plain text only: these feed an image generator
const norm = (s) => String(s ?? '').toLowerCase().replace(/[\u2010-\u2015]/g, '-');

// Which of the caption-analysis attributes does this segment talk about? (style is generic, colours are secondary)
const GROUPS = ['pattern', 'construction', 'material', 'pile', 'features', 'style'];
const stemRe = (group, value) => {
  const words = value.split('_').map((w) => (w.length > 5 ? w.slice(0, 5) : w));
  const stem = words.join('[ -]?');
  return new RegExp(group === 'pile' && value !== 'shag' ? `\\b${stem}[ -]?pile` : `\\b${stem}`);
};
const supportFor = (text) => {
  const rows = [];
  for (const g of GROUPS) {
    for (const r of Array.isArray(mentions[g]) ? mentions[g] : []) {
      if (r && r.value && stemRe(g, r.value).test(text)) rows.push({ group: g, value: r.value, posts: r.posts });
    }
  }
  return rows.sort((a, b) => b.posts - a.posts);
};
const median = (nums) => { const s = [...nums].sort((a, b) => a - b); return s.length ? s[Math.floor((s.length - 1) / 2)] : 0; };
const levelOf = (rows) => {
  if (!rows.length || !totalPosts) return 'unverified';
  const share = median(rows.map((r) => r.posts)) / totalPosts;
  return share < 0.2 ? 'weak' : share <= 0.5 ? 'moderate' : 'stronger';
};
const HAS_NUMBER_CLAIM = /\d|\$|amazon|prefer|demand|popular|growing|bestsell|sales/i;

// Description sentences that quote Amazon, listings, posts, numbers or prices are AI claims we cannot verify: drop them
const safeDesc = (d) => clean(d, 800).split(/(?<=[.!?])\s+/).filter((x) => !/amazon|listing|posts?\b|\d|\$/i.test(x)).join(' ').slice(0, 400);

const segments = output.micro_segments
  .filter((s) => s && typeof s === 'object' && clean(s.name, 60).length >= 2)
  .slice(0, 3)
  .map((s) => {
    const text = norm([s.name, safeDesc(s.description), ...(Array.isArray(s.visual_characteristics) ? s.visual_characteristics : [])].join(' '));
    const rows = supportFor(text);
    const level = levelOf(rows);
    const weakest = rows.length ? rows[rows.length - 1] : null;
    // show the three best-supported attributes AND the weakest one, so a segment cannot hide its weak spot
    const shown = rows.slice(0, 3);
    if (rows.length > 3) shown.push(weakest);
    const verified = shown.map((r) => `${r.group}: ${r.value.replace(/_/g, ' ')} mentioned in ${r.posts} of ${totalPosts} posts`);
    return {
      name: clean(s.name, 60),
      description: safeDesc(s.description),
      visual_characteristics: list(s.visual_characteristics, 60, 5),
      color_palette: list(s.color_palette, 30, 5),
      typical_materials: list(s.typical_materials, 30, 5),
      target_rooms: list(s.target_rooms, 30, 4),
      price_positioning: ['value', 'mid-range', 'premium'].includes(s.price_positioning) ? s.price_positioning : 'mid-range',
      trend_signals: [...verified, ...list(s.trend_signals, 200, 8).filter((t) => !HAS_NUMBER_CLAIM.test(t)).slice(0, 2).map((t) => `AI note: ${t}`)].slice(0, 6),
      image_prompt_keywords: (Array.isArray(s.image_prompt_keywords) ? s.image_prompt_keywords : []).map(keyword).filter((k) => k.length >= 3).slice(0, 6),
      support_level: level,                                   // unverified | weak | moderate | stronger (median share of posts mentioning the segment's attributes)
      weakest_attribute: weakest ? `${weakest.group}: ${weakest.value.replace(/_/g, ' ')} (${weakest.posts} of ${totalPosts} posts)` : null,
      confidence: level === 'moderate' || level === 'stronger' ? 'medium' : 'low',   // never "high": small, old, curated snapshot
      social_support: rows.slice(0, 6),
    };
  });

const order = { stronger: 0, moderate: 1, weak: 2, unverified: 3 };
segments.sort((a, b) => order[a.support_level] - order[b.support_level]);
return out(segments, segments.length ? null : 'no_segments');

// Split micro-segments for individual image generation (course code + reason)
const t = $input.first().json;
const segments = t.microSegments || [];

if (segments.length === 0) {
  return [{ json: { segment: null, skip: true, errorReason: t.errorReason || 'no_segments' } }];
}

return segments.map(segment => ({ json: { segment, errorReason: null } }));

