parameters.jsCode:
// Parse Blog Knowledge | Mode: Run Once for All Items
// Turns the AI's list of claims into the course-shaped knowledge object (materials, sizing, style_insights,
// buyer_guidance, care) and keeps ONLY what can be proved from the documents:
//  - every claim must quote its document (the quote is searched in the document text; no match = dropped)
//  - a claim may only contain numbers (sizes, prices, years) that are in its quote, and its wording must stay close to the quote
//  - market figures ($ amounts, percentages) are found by CODE in the document text, not by the AI
// This node never fails the run: problems give empty fields and a knowledgeStatus the report can explain.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const clean = (s, n) => String(s ?? '').replace(/[\u2010-\u2015]/g, '-').replace(/\s+/g, ' ').trim().slice(0, n);
const norm = (s) => String(s ?? '').replace(/(?<=\d),(?=\d{3})/g, '').toLowerCase().replace(/[\u2010-\u2015]/g, '-').replace(/[\u2018\u2019]/g, "'").replace(/[^a-z0-9%$.' -]+/g, ' ').replace(/\s+/g, ' ').trim();

const docs = arr(safe(() => $('Collect Report Data').first().json.report.knowledge_docs, []));

// allowed fields: how many claims to keep, and whether the claim needs a key (a material, or a price tier)
const FIELDS = {
  'materials.recommendation': { max: 3 },
  'materials.durability': { max: 4, keyed: true },
  'materials.care_need': { max: 4, keyed: true },
  'sizing.living_room': { max: 1 },
  'sizing.bedroom': { max: 1 },
  'sizing.dining': { max: 1 },
  'sizing.rule': { max: 3 },
  'style.trending': { max: 4 },
  'style.color_advice': { max: 1 },
  'style.pattern_tip': { max: 1 },
  'buyer.quality_indicator': { max: 3 },
  'buyer.consideration': { max: 3 },
  'buyer.price_tier': { max: 3, keyed: true, keys: ['budget', 'mid', 'premium'] },
  'care.cleaning': { max: 1 },
  'care.maintenance': { max: 3 },
  'care.lifespan': { max: 1 },
  'market.insight': { max: 3 },
  'customer.insight': { max: 3 },
  'risk': { max: 3 },
};
const blank = () => ({
  materials: { recommendations: [], durability: {}, care_needs: {} },
  sizing: { living_room: null, bedroom: null, dining: null, rules: [] },
  style_insights: { trending: [], color_advice: null, pattern_tips: null },
  buyer_guidance: { quality_indicators: [], considerations: [], price_tiers: {} },
  care: { cleaning: null, maintenance: [], lifespan: null },
  market_insights: [], customer_insights: [], category_trends: [], risks: [],
  evidence: [],
  market_figures: [],
});
const done = (status, knowledge, extra) => [{ json: { blogKnowledge: { ...blank(), ...knowledge }, knowledgeStatus: status, documents_used: docs.length, dropped_unverified: 0, extractedAt: new Date().toISOString(), ...extra } }];

// market figures: found by code, with where they were found
const FIG = /(?:\$|\b(?:USD|US\$|EUR|GBP)\s?|[\u20AC\u00A3])\s?\d[\d,]*(?:\.\d+)?\s?(?:trillion|billion|million|bn|k|m|b)?\b|\b\d+(?:\.\d+)?\s?%/gi;
const found = [];
for (const d of docs) {
  const seen = new Set();
  for (const m of String(d.text).matchAll(FIG)) {
    const figure = m[0].trim();
    if (seen.has(figure)) continue;
    const context = clean(d.text.slice(Math.max(0, m.index - 70), m.index + m[0].length + 70), 160);
    // keep a figure only if the words right around it say what kind of figure it is: a percentage must be a CAGR or a share,
    // a money amount must be about the market, its size, value, revenue or sales (this drops house prices, blend ratios and the like)
    const near = String(d.text).slice(Math.max(0, m.index - 35), m.index + m[0].length + 35).toLowerCase().replace(/\s/g, '');
    if (figure.endsWith('%') ? !/cagr|share/.test(near) : !/market|size|industry|revenue|sales|value/.test(near)) continue;
    seen.add(figure);
    const type = !figure.endsWith('%') ? 'money amount' : /cagr/.test(near) ? 'annual growth rate (CAGR)' : 'share of a market or segment';
    found.push({ figure, type, context, source_id: d.id, source_title: d.title, kind: d.kind });
  }
}
// money amounts first (a market size is a money amount), then percentages: at most 10 in total
const figures = [...found.filter((f) => !f.figure.endsWith('%')).slice(0, 6), ...found.filter((f) => f.figure.endsWith('%')).slice(0, 4)];

if (!docs.length) return done('no_documents', {});

const input = $input.first().json;
let output = input.output;
if (input.error !== undefined || output === undefined || output === null || (typeof output === 'string' && output.trim() === '')) return done('ai_unavailable', { market_figures: figures });

if (typeof output === 'string') {
  output = output.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try {
    output = JSON.parse(output);
  } catch (e) {
    const a = output.indexOf('{');
    const b = output.lastIndexOf('}');
    try { output = JSON.parse(output.slice(a, b + 1)); } catch (e2) { return done('ai_output_invalid', { market_figures: figures }); }
  }
}
if (!output || typeof output !== 'object' || Array.isArray(output)) return done('ai_output_invalid', { market_figures: figures });

// the stored article text often has spaces inside words ("Mark et", "Polypr opylene"): quotes are matched with all spaces removed
const squash = (s) => norm(s).replace(/(?<!\d)\.|\.(?!\d)/g, '').replace(/ /g, '');   // also ignores full stops (except inside numbers): a quote may end at a comma in the text
const textById = new Map(docs.map((d) => [d.id, squash(d.text + ' ' + d.title)]));
// a claim's value must stay close to its quote: at least half of the value's longer words (first six letters) must occur in the quote
const STOP = new Set(['which', 'their', 'there', 'these', 'those', 'about', 'while', 'would', 'could', 'should', 'being', 'where', 'other', 'every', 'still']);
const supportRatio = (value, quote) => {
  const words = (String(value).toLowerCase().match(/[a-z]{5,}/g) || []).filter((w) => !STOP.has(w));
  if (!words.length) return 1;
  const q = squash(quote);
  return words.filter((w) => q.includes(w.slice(0, 6))).length / words.length;
};
const hasNumber = (text, n) => new RegExp(`(?<![\\d.])${n.replace(/[.$]/g, '\\$&')}(?![\\d])`).test(text);
let dropped = 0;
const kept = new Map();      // field -> verified claims
const seenValues = new Set();

for (const c of arr(output.claims).slice(0, 60)) {
  const spec = c && typeof c === 'object' && Object.prototype.hasOwnProperty.call(FIELDS, c.field) ? FIELDS[c.field] : null;   // own keys only: "constructor" and "__proto__" are not fields
  const value = clean(c && c.value, c && c.field === 'materials.durability' ? 120 : 240);
  const quote = norm(c && c.evidence_quote);
  const id = String((c && c.source_id) || '').trim();
  const text = textById.get(id);
  let key = null;
  let ok = !!(spec && text && value.length >= 3 && quote.split(' ').length >= 4 && text.includes(squash(c.evidence_quote)));
  if (ok && spec.keyed) {
    key = clean(c.key, 30).toLowerCase();
    ok = /^[a-z][a-z -]{1,29}$/.test(key) && (!spec.keys || spec.keys.includes(key));
  }
  if (ok) ok = supportRatio(value, c.evidence_quote) >= 0.5;
  // every number in the claim (size, price, year) must be in its quote
  if (ok) ok = (`${value} ${key || ''}`.replace(/(?<=\d),(?=\d{3})/g, '').match(/\d+(?:\.\d+)?/g) || []).every((n) => hasNumber(quote, n));
  const dupe = `${c && c.field}|${key}|${norm(value)}`;
  if (ok && (seenValues.has(dupe) || (kept.get(c.field) || []).length >= spec.max)) ok = false;
  if (!ok) { dropped++; continue; }
  seenValues.add(dupe);
  if (!kept.has(c.field)) kept.set(c.field, []);
  kept.get(c.field).push({ field: c.field, key, text: value, source_id: id, source_title: (docs.find((d) => d.id === id) || {}).title || '', evidence_quote: clean(c.evidence_quote, 200) });
}

// build the course-shaped object from the verified claims only
const k = blank();
const all = [...kept.values()].flat();
const list = (f) => (kept.get(f) || []);
const one = (f) => (list(f)[0] ? list(f)[0].text : null);
const asInsight = (f) => list(f).map((x) => ({ insight: x.text, source_id: x.source_id, source_title: x.source_title, evidence_quote: x.evidence_quote }));
k.materials.recommendations = list('materials.recommendation').map((x) => x.text);
for (const x of list('materials.durability')) k.materials.durability[x.key] = x.text;
for (const x of list('materials.care_need')) k.materials.care_needs[x.key] = x.text;
k.sizing = { living_room: one('sizing.living_room'), bedroom: one('sizing.bedroom'), dining: one('sizing.dining'), rules: list('sizing.rule').map((x) => x.text) };
k.style_insights = { trending: list('style.trending').map((x) => x.text), color_advice: one('style.color_advice'), pattern_tips: one('style.pattern_tip') };
k.buyer_guidance = { quality_indicators: list('buyer.quality_indicator').map((x) => x.text), considerations: list('buyer.consideration').map((x) => x.text), price_tiers: {} };
for (const x of list('buyer.price_tier')) k.buyer_guidance.price_tiers[x.key] = x.text;
k.care = { cleaning: one('care.cleaning'), maintenance: list('care.maintenance').map((x) => x.text), lifespan: one('care.lifespan') };
// the shapes the market, risk and recommendation sections already read
k.market_insights = asInsight('market.insight');
k.customer_insights = asInsight('customer.insight');
k.category_trends = asInsight('style.trending');
k.risks = asInsight('risk');
k.evidence = all.map(({ field, key, text, source_id, source_title, evidence_quote }) => ({ field, key, text, source_id, source_title, evidence_quote }));
k.market_figures = figures;

return done(all.length ? 'ok' : 'no_verified_insights', k, { dropped_unverified: dropped });

// Scope Generator | Mode: Run Once for All Items
// Builds the "Scope of Research" section from counts and dates computed by the workflow. No AI, no free text:
// everything inserted into the HTML is escaped.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const r = safe(() => $('Collect Report Data').first().json.report, {});
const k = safe(() => $('Parse Blog Knowledge').first().json, {});
const p = r.products || {};
const s = r.social || {};
const st = r.run_status || {};

const dateRange = (d) => (d && d.n > 0 ? `${esc(d.oldest)} to ${esc(d.newest)}` : null);
const dates = s.post_dates || {};
const socialDates = ['instagram', 'pinterest'].map((src) => (dateRange(dates[src]) ? `${src === 'instagram' ? 'Instagram' : 'Pinterest'}: ${dateRange(dates[src])}` : null)).filter(Boolean).join('; ') || 'dates not available';
const row = (a, b, c) => `<tr><td>${a}</td><td>${b}</td><td>${c}</td></tr>`;

const rows = [
  row('Amazon products',
    p.products_analyzed ? `${esc(p.products_analyzed)} products analysed${p.products_returned ? ` (of ${esc(p.products_returned)} returned)` : ''}` : 'No products analysed',
    'Attributes were read from product text and checked against keywords; counts and shares are computed by the workflow'),
  row('Instagram and Pinterest posts',
    s.posts_analyzed ? `${esc(s.posts_analyzed)} posts (${esc(s.instagram_posts)} Instagram, ${esc(s.pinterest_posts)} Pinterest)` : 'No posts analysed',
    `Captions and hashtags only; images were not analysed. Post dates: ${socialDates}`),
  row('Blog articles',
    st.blog_documents ? `${esc(st.blog_documents)} articles` : 'None available',
    'Insights are kept only when they quote the article'),
  row('Market articles',
    st.market_documents ? `${esc(st.market_documents)} articles` : 'None available',
    'Any market figures are reported by the article and are not verified'),
  row('Trend segments',
    `${esc(st.segments || 0)} segments, ${esc(st.images || 0)} illustrated`,
    'Segments are built from product and social evidence; images are AI-generated illustrations of the style, not product photos'),
];

const limits = Array.isArray(r.warnings) ? r.warnings : [];
const html = [
  '<h2>Scope of Research</h2>',
  `<p>This report covers the <strong>${esc(r.category || 'rug')}</strong> category${r.generated_on ? `, generated on ${esc(r.generated_on)}` : ''}. It combines product listings, social posts and trade articles from a stored data snapshot, not a live feed.</p>`,
  `<table><thead><tr><th>Source</th><th>What was analysed</th><th>Notes</th></tr></thead><tbody>${rows.join('')}</tbody></table>`,
  '<h3>Limits of this data</h3>',
  limits.length ? `<ul>${limits.map((w) => `<li>${esc(w)}</li>`).join('')}</ul>` : '<p>No data warnings were raised.</p>',
  '<h3>Method</h3>',
  '<ul><li>All counts, shares and prices are computed by the workflow, not written by an AI model.</li><li>No sales, traffic or search-volume data was available, so no section measures demand.</li></ul>',
].join('');

return [{ json: { section: 'scope', html, knowledge_status: k.knowledgeStatus || null } }];

